"use client";

import * as React from "react";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Airy docs Accordion: a stack of questions inside one hairline card, the
 * way docs pages group an FAQ or expandable fields.
 */
const Accordion = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Root
    ref={ref}
    data-slot="accordion"
    className={cn("w-full rounded-xl border border-border px-4", className)}
    {...props}
  />
));
Accordion.displayName = "Accordion";

/** Airy docs AccordionItem: one row, divided from the next by a hairline. */
const AccordionItem = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Item.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    data-slot="accordion-item"
    className={cn("border-b border-border last:border-b-0", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

/**
 * Airy docs AccordionTrigger: a right-pointing chevron before the question.
 * The chevron turns down as the answer opens, the way docs expandables do.
 */
const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AccordionPrimitive.Trigger.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      data-slot="accordion-trigger"
      className={cn(
        "group/trigger flex flex-1 items-center gap-2.5 rounded-md py-3.5 text-start",
        "text-sm font-medium text-foreground",
        "outline-none focus-visible:ring-3 focus-visible:ring-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
        className,
      )}
      {...props}
    >
      <ChevronRightIcon
        aria-hidden="true"
        className="size-4 shrink-0 text-muted-foreground transition-transform duration-fast ease-out group-data-[panel-open]/trigger:rotate-90"
      />
      {children}
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = "AccordionTrigger";

/**
 * Airy docs AccordionContent: the answer in secondary ink, indented under
 * the question. The panel grows to its measured height as it opens.
 */
const AccordionContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Panel.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Panel
    ref={ref}
    data-slot="accordion-content"
    className={cn(
      "h-(--accordion-panel-height) overflow-hidden text-sm leading-relaxed text-(--foreground-secondary)",
      "transition-[height] duration-base ease-out",
      "data-[starting-style]:h-0 data-[ending-style]:h-0",
    )}
    {...props}
  >
    <div className={cn("pb-4 ps-6.5", className)}>{children}</div>
  </AccordionPrimitive.Panel>
));
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

// Feather, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "feather:chevron-right"
// [BD-1029]
function ChevronRightIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="m9 18l6-6l-6-6"/>
    </svg>
  );
}
